from pathlib import Path
root=Path('tach-xep-pdf-v2.3.2')
p=root/'TachXepTrangPDF.cs'
s=p.read_text(encoding='utf-8-sig')

def rep(old,new,label,count=1):
    global s
    if old not in s:
        raise SystemExit('v291 marker missing: '+label)
    s=s.replace(old,new,count)

# Version identity only. No PDF engine behavior changes.
rep('internal const string Version = "2.9.0";','internal const string Version = "2.9.1";','diag version')
rep('startup-v2.9.0.log','startup-v2.9.1.log','startup log')
rep('private const string AppVersion = "2.9.0";','private const string AppVersion = "2.9.1";','app version')

# Compact top-toolbar button factory: keeps all top actions on one row at minimum supported width.
anchor='''        private Button MakeButton(string text, int width, bool prominent)\n'''
helper='''        private Button MakeTopButton(string text, int width, bool prominent)\n        {\n            FluentButton b = new FluentButton(prominent); b.Text = text; b.Height = 38; b.AutoEllipsis = false; b.Padding = new Padding(5,0,5,0); b.Font = UiTheme.Font(8.4f, FontStyle.Bold);\n            Size measured = TextRenderer.MeasureText(text ?? "", b.Font, new Size(int.MaxValue, int.MaxValue), TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix);\n            b.Width = Math.Max(width, measured.Width + b.Padding.Horizontal + 8); b.Height = Math.Max(38, measured.Height + 14); return b;\n        }\n\n'''
if anchor not in s: raise SystemExit('v291 marker missing: MakeButton anchor')
s=s.replace(anchor,helper+anchor,1)

# Top row: Save All is immediately after Save Original. Compact only this row, not global buttons.
rep('''            Button open = MakeButton("Mở PDF", 100, true); open.Margin = new Padding(0, 0, 8, 0); open.Click += delegate { OpenPdf(); }; actions.Controls.Add(open); _toolTip = _toolTip ?? new ToolTip(); _toolTip.SetToolTip(open, "Có thể chọn một hoặc nhiều tệp PDF cùng lúc.");\n            _btnAuto = MakeButton("TỰ XOAY THÔNG MINH", 188, true); _btnAuto.Margin = new Padding(0, 0, 8, 0); _btnAuto.Click += async delegate { await AutoRotateAsync(); }; actions.Controls.Add(_btnAuto);\n            _btnSplit = MakeButton("TỰ CHIA & SẮP XẾP", 190, true); _btnSplit.Margin = new Padding(0, 0, 8, 0); _btnSplit.Click += delegate { SplitAndArrange(); }; actions.Controls.Add(_btnSplit);\n            _btnExport = MakeButton("Xuất PDF", 112, true); _btnExport.Margin = new Padding(0, 0, 8, 0); _btnExport.Click += async delegate { await ExportPdfAsync(false); }; actions.Controls.Add(_btnExport);\n            _btnSaveOriginal = MakeButton("Lưu vào file gốc", 146, false); _btnSaveOriginal.Margin = new Padding(0, 0, 8, 0); _btnSaveOriginal.Click += async delegate { await ExportPdfAsync(true); }; actions.Controls.Add(_btnSaveOriginal); StyleGroupedButton(_btnSaveOriginal, UiTheme.Save);\n            _btnRestoreOriginal = MakeButton("Khôi phục PDF gốc", 154, false); _btnRestoreOriginal.Margin = new Padding(0, 0, 8, 0); _btnRestoreOriginal.Click += delegate { RestoreOriginalPdf(); }; actions.Controls.Add(_btnRestoreOriginal); StyleGroupedButton(_btnRestoreOriginal, UiTheme.Restore);\n''','''            Button open = MakeTopButton("Mở PDF", 78, true); open.Margin = new Padding(0, 0, 4, 0); open.Click += delegate { OpenPdf(); }; actions.Controls.Add(open); _toolTip = _toolTip ?? new ToolTip(); _toolTip.SetToolTip(open, "Có thể chọn một hoặc nhiều tệp PDF cùng lúc.");\n            _btnAuto = MakeTopButton("TỰ XOAY THÔNG MINH", 152, true); _btnAuto.Margin = new Padding(0, 0, 4, 0); _btnAuto.Click += async delegate { await AutoRotateAsync(); }; actions.Controls.Add(_btnAuto);\n            _btnSplit = MakeTopButton("TỰ CHIA & SẮP XẾP", 156, true); _btnSplit.Margin = new Padding(0, 0, 4, 0); _btnSplit.Click += delegate { SplitAndArrange(); }; actions.Controls.Add(_btnSplit);\n            _btnExport = MakeTopButton("Xuất PDF", 86, true); _btnExport.Margin = new Padding(0, 0, 4, 0); _btnExport.Click += async delegate { await ExportPdfAsync(false); }; actions.Controls.Add(_btnExport);\n            _btnSaveOriginal = MakeTopButton("Lưu vào file gốc", 126, false); _btnSaveOriginal.Margin = new Padding(0, 0, 4, 0); _btnSaveOriginal.Click += async delegate { await ExportPdfAsync(true); }; actions.Controls.Add(_btnSaveOriginal); StyleGroupedButton(_btnSaveOriginal, UiTheme.Save);\n            _btnSaveAllOriginal = MakeTopButton("Lưu tất cả vào file gốc", 162, false); _btnSaveAllOriginal.Margin = new Padding(0, 0, 4, 0); _btnSaveAllOriginal.Click += async delegate { await SaveAllModifiedToOriginalAsync(); }; actions.Controls.Add(_btnSaveAllOriginal); StyleGroupedButton(_btnSaveAllOriginal, UiTheme.Save); _toolTip.SetToolTip(_btnSaveAllOriginal, "Lưu tất cả PDF đã chỉnh sửa vào chính các tệp PDF gốc.");\n            _btnRestoreOriginal = MakeTopButton("Khôi phục PDF gốc", 140, false); _btnRestoreOriginal.Margin = new Padding(0); _btnRestoreOriginal.Click += delegate { RestoreOriginalPdf(); }; actions.Controls.Add(_btnRestoreOriginal); StyleGroupedButton(_btnRestoreOriginal, UiTheme.Restore);\n''','compact top toolbar')

# Remove the old second-row Save All button.
rep('''            _btnSaveAllOriginal = MakeButton("Lưu tất cả gốc", 138, false); _btnSaveAllOriginal.Margin = new Padding(0,0,5,0); _btnSaveAllOriginal.Click += async delegate { await SaveAllModifiedToOriginalAsync(); }; pageTools.Controls.Add(_btnSaveAllOriginal); StyleGroupedButton(_btnSaveAllOriginal, UiTheme.Save); _toolTip.SetToolTip(_btnSaveAllOriginal, "Lưu tất cả PDF đã chỉnh sửa vào chính các tệp PDF gốc.");\n''','', 'remove old page-tools save all')

# Page-order navigation: all four controls always share one row.
rep('''            FlowLayoutPanel navRow = new FlowLayoutPanel(); navRow.Dock = DockStyle.Fill; navRow.WrapContents = true; navRow.Padding = new Padding(0,2,0,2); leftLayout.Controls.Add(navRow,0,2);\n            Button upOne = MakeButton("Lên 1", 67, false); upOne.Height=32; upOne.Margin=new Padding(0,0,4,0); upOne.Click += delegate { MoveSelectedBy(-1); }; navRow.Controls.Add(upOne);\n            Button downOne = MakeButton("Xuống 1", 73, false); downOne.Height=32; downOne.Margin=new Padding(0,0,4,0); downOne.Click += delegate { MoveSelectedBy(1); }; navRow.Controls.Add(downOne);\n            Button toTop = MakeButton("Lên đầu", 78, false); toTop.Height=32; toTop.Margin=new Padding(0,0,4,0); toTop.Click += delegate { MoveSelectedToEdge(true); }; navRow.Controls.Add(toTop);\n            Button toBottom = MakeButton("Xuống cuối", 88, false); toBottom.Height=32; toBottom.Margin=new Padding(0); toBottom.Click += delegate { MoveSelectedToEdge(false); }; navRow.Controls.Add(toBottom);\n''','''            FlowLayoutPanel navRow = new FlowLayoutPanel(); navRow.Dock = DockStyle.Fill; navRow.WrapContents = false; navRow.AutoScroll = false; navRow.Padding = new Padding(0,2,0,2); leftLayout.Controls.Add(navRow,0,2);\n            Button upOne = MakeButton("Lên 1", 55, false); upOne.Width=55; upOne.Height=32; upOne.Font=UiTheme.Font(8.0f, FontStyle.Bold); upOne.Padding=new Padding(2,0,2,0); upOne.Margin=new Padding(0,0,4,0); upOne.Click += delegate { MoveSelectedBy(-1); }; navRow.Controls.Add(upOne);\n            Button downOne = MakeButton("Xuống 1", 62, false); downOne.Width=62; downOne.Height=32; downOne.Font=UiTheme.Font(8.0f, FontStyle.Bold); downOne.Padding=new Padding(2,0,2,0); downOne.Margin=new Padding(0,0,4,0); downOne.Click += delegate { MoveSelectedBy(1); }; navRow.Controls.Add(downOne);\n            Button toTop = MakeButton("Lên đầu", 66, false); toTop.Width=66; toTop.Height=32; toTop.Font=UiTheme.Font(8.0f, FontStyle.Bold); toTop.Padding=new Padding(2,0,2,0); toTop.Margin=new Padding(0,0,4,0); toTop.Click += delegate { MoveSelectedToEdge(true); }; navRow.Controls.Add(toTop);\n            Button toBottom = MakeButton("Xuống cuối", 78, false); toBottom.Width=78; toBottom.Height=32; toBottom.Font=UiTheme.Font(8.0f, FontStyle.Bold); toBottom.Padding=new Padding(2,0,2,0); toBottom.Margin=new Padding(0); toBottom.Click += delegate { MoveSelectedToEdge(false); }; navRow.Controls.Add(toBottom);\n''','nav one row')

# History buttons: full, simple wording with larger, clearer circular arrows.
rep('''            _btnUndo = MakeButton("Quay lại", 104, false); _btnUndo.Margin = new Padding(0, 0, 5, 0); _btnUndo.Image = CreateHistoryIcon(false); _btnUndo.TextImageRelation = TextImageRelation.ImageBeforeText; _btnUndo.ImageAlign = ContentAlignment.MiddleLeft; _btnUndo.Click += delegate { Undo(); }; manualButtons.Controls.Add(_btnUndo); StyleGroupedButton(_btnUndo, UiTheme.History);\n            _btnRedo = MakeButton("Tiến lại", 104, false); _btnRedo.Margin = new Padding(0, 0, 8, 0); _btnRedo.Image = CreateHistoryIcon(true); _btnRedo.TextImageRelation = TextImageRelation.ImageBeforeText; _btnRedo.ImageAlign = ContentAlignment.MiddleLeft; _btnRedo.Click += delegate { Redo(); }; manualButtons.Controls.Add(_btnRedo); StyleGroupedButton(_btnRedo, UiTheme.History);\n''','''            _btnUndo = MakeButton("Quay lại", 116, false); _btnUndo.Width = 116; _btnUndo.Padding = new Padding(4,0,4,0); _btnUndo.Margin = new Padding(0, 0, 5, 0); _btnUndo.Image = CreateHistoryIcon(false); _btnUndo.TextImageRelation = TextImageRelation.ImageBeforeText; _btnUndo.ImageAlign = ContentAlignment.MiddleLeft; _btnUndo.TextAlign = ContentAlignment.MiddleRight; _btnUndo.Click += delegate { Undo(); }; manualButtons.Controls.Add(_btnUndo); StyleGroupedButton(_btnUndo, UiTheme.History);\n            _btnRedo = MakeButton("Tiến lên", 116, false); _btnRedo.Width = 116; _btnRedo.Padding = new Padding(4,0,4,0); _btnRedo.Margin = new Padding(0, 0, 8, 0); _btnRedo.Image = CreateHistoryIcon(true); _btnRedo.TextImageRelation = TextImageRelation.ImageBeforeText; _btnRedo.ImageAlign = ContentAlignment.MiddleLeft; _btnRedo.TextAlign = ContentAlignment.MiddleRight; _btnRedo.Click += delegate { Redo(); }; manualButtons.Controls.Add(_btnRedo); StyleGroupedButton(_btnRedo, UiTheme.History);\n''','history buttons')

rep('''        private static Bitmap CreateHistoryIcon(bool forward)\n        {\n            Bitmap icon = new Bitmap(20,20,PixelFormat.Format32bppArgb);\n            using(Graphics g = Graphics.FromImage(icon))\n            using(Pen pen = new Pen(Color.White,2.2f))\n            using(SolidBrush brush = new SolidBrush(Color.White))\n            {\n                g.SmoothingMode = SmoothingMode.AntiAlias;\n                RectangleF arc = new RectangleF(3.5f,3.5f,13f,13f);\n                if (forward)\n                {\n                    g.DrawArc(pen,arc,205,280);\n                    g.FillPolygon(brush,new PointF[]{new PointF(16.8f,4.0f),new PointF(11.7f,4.2f),new PointF(15.0f,8.0f)});\n                }\n                else\n                {\n                    g.DrawArc(pen,arc,55,280);\n                    g.FillPolygon(brush,new PointF[]{new PointF(3.2f,4.0f),new PointF(8.3f,4.2f),new PointF(5.0f,8.0f)});\n                }\n            }\n            return icon;\n        }\n''','''        private static Bitmap CreateHistoryIcon(bool forward)\n        {\n            Bitmap icon = new Bitmap(24,24,PixelFormat.Format32bppArgb);\n            using(Graphics g = Graphics.FromImage(icon))\n            using(Pen pen = new Pen(Color.White,2.8f))\n            using(SolidBrush brush = new SolidBrush(Color.White))\n            {\n                g.SmoothingMode = SmoothingMode.AntiAlias;\n                pen.StartCap = LineCap.Round; pen.EndCap = LineCap.Round;\n                RectangleF arc = new RectangleF(3.0f,3.0f,18.0f,18.0f);\n                if (forward)\n                {\n                    g.DrawArc(pen, arc, 205, 255);\n                    g.FillPolygon(brush, new PointF[]{ new PointF(21.5f,5.0f), new PointF(14.8f,4.2f), new PointF(19.0f,10.0f) });\n                }\n                else\n                {\n                    g.DrawArc(pen, arc, 80, 255);\n                    g.FillPolygon(brush, new PointF[]{ new PointF(2.5f,5.0f), new PointF(9.2f,4.2f), new PointF(5.0f,10.0f) });\n                }\n            }\n            return icon;\n        }\n''','history icon')

# Keep labels stable so they never truncate when history count reaches 10.
rep('''            if (_btnUndo != null) _btnUndo.Text = "Quay lại" + (_undo.Count > 0 ? " (" + _undo.Count.ToString() + ")" : "");\n            if (_btnRedo != null) _btnRedo.Text = "Tiến lại" + (_redo.Count > 0 ? " (" + _redo.Count.ToString() + ")" : "");\n''','''            if (_btnUndo != null) _btnUndo.Text = "Quay lại";\n            if (_btnRedo != null) _btnRedo.Text = "Tiến lên";\n''','stable history labels')

# Wording and smoke expectations.
s=s.replace('Tiến lại', 'Tiến lên')
s=s.replace('Lưu tất cả gốc', 'Lưu tất cả vào file gốc')

p.write_text(s,encoding='utf-8-sig')
